/// Keywords match at the start of a word ("fit" matches "fits", not "benefit").
AssistantIntent answerFor(String question) {
  final s = question.toLowerCase();
  bool hit(String k) => RegExp('(^|[^a-z])${RegExp.escape(k)}').hasMatch(s);
  for (final i in intents) {
    if (i.keywords.any(hit)) return i;
  }
  return intentDefault;
}
